import React, { useEffect, useState } from 'react';
import axios from 'axios';

const API_URL = 'http://localhost:3000';

interface Machine {
  id: number;
  name: string;
  status: string;
  production: number;
  temperature: number;
}

interface Alert {
  id: number;
  machine: string;
  type: string;
  message: string;
}

export default function App() {
  const [machines, setMachines] = useState<Machine[]>([]);
  const [alerts, setAlerts] = useState<Alert[]>([]);

  useEffect(() => {
    axios.get(`${API_URL}/api/machines`).then(res => setMachines(res.data));
    axios.get(`${API_URL}/api/alerts`).then(res => setAlerts(res.data));
  }, []);

  const operando = machines.filter(m => m.status === 'operando').length;
  const falha = machines.filter(m => m.status === 'falha').length;
  const manutencao = machines.filter(m => m.status === 'manutenção').length;
  const mediaProducao = machines.length > 0
    ? Math.round(machines.reduce((a, m) => a + m.production, 0) / machines.length)
    : 0;

  const statusColor = (status: string) => {
    if (status === 'operando') return '#22c55e';
    if (status === 'falha') return '#ef4444';
    return '#f59e0b';
  };

  const statusBg = (status: string) => {
    if (status === 'operando') return '#052e16';
    if (status === 'falha') return '#450a0a';
    return '#271404';
  };

  return (
    <div style={{ minHeight: '100vh', background: '#0a0f1e', color: '#e2e8f0', fontFamily: 'Inter, sans-serif', padding: '24px' }}>

      {/* Header */}
      <div style={{ marginBottom: '32px' }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: '12px', marginBottom: '4px' }}>
          <span style={{ fontSize: '28px' }}>⚙️</span>
          <h1 style={{ fontSize: '26px', fontWeight: '700', color: '#60a5fa', margin: 0 }}>SmartFactory Dashboard</h1>
        </div>
        <p style={{ color: '#64748b', margin: 0, fontSize: '14px' }}>Monitoramento Industrial em Tempo Real</p>
      </div>

      {/* Cards de resumo */}
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(4, 1fr)', gap: '16px', marginBottom: '32px' }}>
        {[
          { label: 'Operando', value: operando, color: '#22c55e' },
          { label: 'Em Falha', value: falha, color: '#ef4444' },
          { label: 'Manutenção', value: manutencao, color: '#f59e0b' },
          { label: 'Produção Média', value: `${mediaProducao}%`, color: '#60a5fa' },
        ].map((card, i) => (
          <div key={i} style={{ background: '#111827', border: '1px solid #1e293b', borderRadius: '12px', padding: '20px' }}>
            <p style={{ color: '#64748b', fontSize: '13px', margin: '0 0 8px' }}>{card.label}</p>
            <p style={{ fontSize: '32px', fontWeight: '700', color: card.color, margin: 0 }}>{card.value}</p>
          </div>
        ))}
      </div>

      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '24px', marginBottom: '24px' }}>

        {/* Lista de máquinas */}
        <div style={{ background: '#111827', border: '1px solid #1e293b', borderRadius: '12px', padding: '20px' }}>
          <h2 style={{ fontSize: '16px', fontWeight: '600', margin: '0 0 16px', color: '#f1f5f9' }}>🏭 Máquinas</h2>
          <div style={{ display: 'flex', flexDirection: 'column', gap: '10px' }}>
            {machines.map(m => (
              <div key={m.id} style={{ background: '#0f172a', borderRadius: '8px', padding: '12px 16px', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                <div>
                  <p style={{ margin: '0 0 4px', fontWeight: '600', fontSize: '14px' }}>{m.name}</p>
                  <p style={{ margin: 0, fontSize: '12px', color: '#64748b' }}>🌡️ {m.temperature}°C &nbsp;|&nbsp; 📦 {m.production}%</p>
                </div>
                <span style={{ background: statusBg(m.status), color: statusColor(m.status), fontSize: '11px', fontWeight: '600', padding: '4px 10px', borderRadius: '20px', border: `1px solid ${statusColor(m.status)}33` }}>
                  {m.status}
                </span>
              </div>
            ))}
          </div>
        </div>

        {/* Gráfico de produção */}
        <div style={{ background: '#111827', border: '1px solid #1e293b', borderRadius: '12px', padding: '20px' }}>
          <h2 style={{ fontSize: '16px', fontWeight: '600', margin: '0 0 16px', color: '#f1f5f9' }}>📊 Produção por Máquina</h2>
          <div style={{ display: 'flex', flexDirection: 'column', gap: '14px' }}>
            {machines.map(m => (
              <div key={m.id}>
                <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: '12px', color: '#94a3b8', marginBottom: '6px' }}>
                  <span>{m.name}</span>
                  <span style={{ color: statusColor(m.status), fontWeight: '600' }}>{m.production}%</span>
                </div>
                <div style={{ height: '8px', background: '#1e293b', borderRadius: '4px' }}>
                  <div style={{ width: `${m.production}%`, height: '100%', background: statusColor(m.status), borderRadius: '4px', transition: 'width 0.5s ease' }} />
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>

      {/* Alertas */}
      <div style={{ background: '#111827', border: '1px solid #1e293b', borderRadius: '12px', padding: '20px' }}>
        <h2 style={{ fontSize: '16px', fontWeight: '600', margin: '0 0 16px', color: '#f1f5f9' }}>🚨 Alertas Recentes</h2>
        <div style={{ display: 'flex', flexDirection: 'column', gap: '10px' }}>
          {alerts.map(a => (
            <div key={a.id} style={{ background: a.type === 'critico' ? '#450a0a' : a.type === 'aviso' ? '#271404' : '#0f172a', border: `1px solid ${a.type === 'critico' ? '#ef444433' : a.type === 'aviso' ? '#f59e0b33' : '#1e293b'}`, borderRadius: '8px', padding: '12px 16px', display: 'flex', gap: '12px', alignItems: 'flex-start' }}>
              <span style={{ fontSize: '16px', marginTop: '1px' }}>{a.type === 'critico' ? '🔴' : a.type === 'aviso' ? '🟡' : '⚪'}</span>
              <div>
                <p style={{ margin: '0 0 2px', fontWeight: '600', fontSize: '13px', color: a.type === 'critico' ? '#fca5a5' : a.type === 'aviso' ? '#fcd34d' : '#94a3b8' }}>{a.machine}</p>
                <p style={{ margin: 0, fontSize: '12px', color: '#64748b' }}>{a.message}</p>
              </div>
            </div>
          ))}
        </div>
      </div>

    </div>
  );
}
